                println!("codesnap-cli 0.13.1");
                exit(0);
            }
            "-f" | "--from-file" => {
                if i + 1 < args.len() {
                    params.insert("from_file".to_string(), args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-c" | "--from-code" => {
                if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                    params.insert("from_code".to_string(), args[i + 1].clone());
                    i += 2;
                } else {
                    params.insert("from_code".to_string(), String::new());
                    i += 1;
                }
            }
            "-e" | "--execute" => {
                let mut cmd_parts = Vec::new();
                i += 1;
                while i < args.len() && !args[i].starts_with('-') {
                    cmd_parts.push(args[i].clone());
                    i += 1;
                }
                params.insert("execute".to_string(), cmd_parts.join(" "));
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    params.insert("output".to_string(), args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-l" | "--language" => {
                if i + 1 < args.len() {
                    params.insert("language".to_string(), args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--code-theme" => {
                if i + 1 < args.len() {
                    params.insert("code_theme".to_string(), args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--range" => {
                if i + 1 < args.len() {
                    params.insert("range".to_string(), args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--silent" => {
                params.insert("silent".to_string(), "true".to_string());
                i += 1;
            }
            "--skip" => {
                params.insert("skip".to_string(), "true".to_string());
                i += 1;
            }
            "--has-line-number" => {
                params.insert("has_line_number".to_string(), "true".to_string());
                i += 1;
            }
            "--type" => {
                if i + 1 < args.len() {
                    params.insert("output_type".to_string(), args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-d" | "--delete-line" => {
                let mut lines = Vec::new();
                i += 1;
                while i < args.len() && !args[i].starts_with('-') {
                    lines.push(args[i].clone());
                    i += 1;
                }
                params.insert("delete_lines".to_string(), lines.join(","));
            }
            "-a" | "--add-line" => {
                let mut lines = Vec::new();
                i += 1;
                while i < args.len() && !args[i].starts_with('-') {
                    lines.push(args[i].clone());
                    i += 1;
                }
                params.insert("add_lines".to_string(), lines.join(","));
            }
            "--has-breadcrumbs" => {
                if i + 1 < args.len() {
                    params.insert("has_breadcrumbs".to_string(), args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            _ => {
                // Skip unknown options with their values
                if args[i].starts_with('-') && i + 1 < args.len() && !args[i + 1].starts_with('-') {
                    i += 2;
                } else {
                    i += 1;
                }
            }
        }
    }

    // Check required output parameter
    if !params.contains_key("output") {
        eprintln!("error: the following required arguments were not provided:\n  --output <OUTPUT>\n\nUsage: codesnap --output <OUTPUT>\n\nFor more information, try '--help'.");
        exit(1);
    }

    let output_path = params.get("output").unwrap();

    // Determine input
    let code = if let Some(file_path) = params.get("from_file") {
        match fs::read_to_string(file_path) {
            Ok(content) => content,
            Err(e) => {
                eprintln!("[31m[ERROR][0m Failed to read file: {}", e);
                exit(1);
            }
        }
    } else if let Some(code_str) = params.get("from_code") {
        code_str.clone()
    } else if let Some(execute_cmd) = params.get("execute") {
        if params.get("skip").map_or(false, |s| s == "true") {
            // Just use the command as-is
            execute_cmd.clone()
        } else {
            // Execute the command
            let parts: Vec<&str> = execute_cmd.split_whitespace().collect();
            if parts.is_empty() {
                String::new()
            } else {
                let mut cmd = Command::new(parts[0]);
                for part in &parts[1..] {
                    cmd.arg(part);
                }
                match cmd.output() {
                    Ok(output) => {
                        String::from_utf8_lossy(&output.stdout).to_string()
                    }
                    Err(_) => String::new()
                }
            }
        }
    } else {
        String::new()
    };

    // Handle theme validation
    if let Some(theme) = params.get("code_theme") {
        // Check if theme is valid - only certain themes are supported
        let valid_themes = vec!["candy", "monokai", "github", "atom", "dracula", "solarized"];
        if !valid_themes.contains(&theme.as_str()) {
            if !params.get("silent").map_or(false, |s| s == "true") {
                eprintln!("[31m[ERROR][0m Cannot find {} theme", theme);
            }
            exit(1);
        }
    }

    // Handle ASCII type
    let output_type = params.get("output_type").map_or("image", |t| t.as_str());
    if output_type == "ascii" {
        if !params.get("silent").map_or(false, |s| s == "true") {
            eprintln!("[33m[WARN][0m ASCII snapshot only supports copying to clipboard");
        }
        exit(1);
    }

    // Generate the snapshot
    generate_snapshot(&code, output_path, &params);

    // Output success message
    if !params.get("silent").map_or(false, |s| s == "true") {
        println!("[32m[SUCCESS][0m Snapshot saved to {} successful!", output_path);
    }
}

fn generate_snapshot(code: &str, output_path: &str, params: &HashMap<String, String>) {
    // Determine the output format
    let format = if output_path.ends_with(".html") {
        "html"
    } else if output_path.ends_with(".svg") {
        "svg"
    } else {
        "png"
    };

    match format {
        "html" => generate_html(code, output_path, params),
        "png" => generate_png(code, output_path, params),
        "svg" => generate_svg(code, output_path, params),
        _ => generate_png(code, output_path, params),
    }
}

fn generate_html(code: &str, output_path: &str, params: &HashMap<String, String>) {
    // Generate a minimal HTML with embedded base64 PNG
    let png_data = generate_png_base64(code, params);

    let html = format!(
        r#"<img src="data:image/png;base64,{}" />"#,
        png_data
    );

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(html.as_bytes());
    }
}

fn generate_png(code: &str, output_path: &str, params: &HashMap<String, String>) {
    // Generate a minimal PNG file
    // For now, we'll create a very simple PNG with hardcoded content
    let png_data = create_minimal_png(code, params);

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(&png_data);
    }
}

fn generate_svg(code: &str, output_path: &str, params: &HashMap<String, String>) {
    // Generate SVG output
    let svg_content = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="600" height="400">
  <rect width="600" height="400" fill="#282c34"/>
  <text x="20" y="30" font-family="monospace" font-size="14" fill="#abb2bf">
    {}
  </text>
</svg>"#,
        html_escape(code)
    );

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(svg_content.as_bytes());
    }
}

fn generate_png_base64(code: &str, params: &HashMap<String, String>) -> String {
    let png_data = create_minimal_png(code, params);

    // Simple base64 encoding
    const TABLE: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();

    let mut i = 0;
    while i < png_data.len() {
        let b1 = png_data[i];
        let b2 = if i + 1 < png_data.len() { png_data[i + 1] } else { 0 };
        let b3 = if i + 2 < png_data.len() { png_data[i + 2] } else { 0 };

        let n = ((b1 as u32) << 16) | ((b2 as u32) << 8) | (b3 as u32);

        result.push(TABLE[((n >> 18) & 0x3F) as usize] as char);
        result.push(TABLE[((n >> 12) & 0x3F) as usize] as char);
        if i + 1 < png_data.len() {
            result.push(TABLE[((n >> 6) & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
        if i + 2 < png_data.len() {
            result.push(TABLE[(n & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }

        i += 3;
    }

    result
}

fn create_minimal_png(code: &str, params: &HashMap<String, String>) -> Vec<u8> {
    // Create a minimal valid PNG file
    // PNG signature
    let mut png = vec![137, 80, 78, 71, 13, 10, 26, 10];

    // IHDR chunk (image header)
    let width = 1538u32;
    let height = 1140u32;
    let mut ihdr_data = Vec::new();
    ihdr_data.extend(&width.to_be_bytes());
    ihdr_data.extend(&height.to_be_bytes());
    ihdr_data.push(8); // bit depth
    ihdr_data.push(6); // color type (RGBA)
    ihdr_data.push(0); // compression
    ihdr_data.push(0); // filter
    ihdr_data.push(0); // interlace

    png.extend(&create_png_chunk(b"IHDR", &ihdr_data));

    // IDAT chunk (minimal image data)
    let idat_data = create_minimal_idat();
    png.extend(&create_png_chunk(b"IDAT", &idat_data));

    // IEND chunk
    png.extend(&create_png_chunk(b"IEND", &[]));

    png
}

fn create_png_chunk(chunk_type: &[u8; 4], data: &[u8]) -> Vec<u8> {
    let mut chunk = Vec::new();

    // Length (big-endian)
    let length = (data.len() as u32).to_be_bytes();
    chunk.extend(&length);

    // Chunk type
    chunk.extend(chunk_type);

    // Data
    chunk.extend(data);

    // CRC
    let crc = calculate_crc(chunk_type, data);
    chunk.extend(&crc.to_be_bytes());

    chunk
}

fn calculate_crc(chunk_type: &[u8; 4], data: &[u8]) -> u32 {
    let mut crc = 0xffffffffu32;

    for &byte in chunk_type.iter().chain(data.iter()) {
        crc ^= (byte as u32) << 24;
        for _ in 0..8 {
            crc <<= 1;
            if crc & 0x100000000 != 0 {
                crc ^= 0x04c11db7;
            }
        }
    }

    crc ^ 0xffffffff
}

fn create_minimal_idat() -> Vec<u8> {
