            let parts: Vec<&str> = execute_cmd.split_whitespace().collect();
            if parts.is_empty() {
                String::new()
            } else {
                let mut cmd = Command::new(parts[0]);
                for part in &parts[1..] {
                    cmd.arg(part);
                }
                match cmd.output() {
                    Ok(output) => {
                        String::from_utf8_lossy(&output.stdout).to_string()
                    }
                    Err(_) => String::new()
                }
            }
        }
    } else {
        String::new()
    };

