    if let Some(theme) = params.get("code_theme") {
        // Check if theme is valid - only certain themes are supported
        let valid_themes = vec!["candy", "monokai", "github", "atom", "dracula", "solarized"];
        if !valid_themes.contains(&theme.as_str()) {
