fn generate_snapshot(code: &str, output_path: &str, params: &HashMap<String, String>) {
    // Determine the output format
    let format = if output_path.ends_with(".html") {
        "html"
    } else if output_path.ends_with(".svg") {
        "svg"
    } else {
        "png"
    };

    match format {
        "html" => generate_html(code, output_path, params),
        "png" => generate_png(code, output_path, params),
        "svg" => generate_svg(code, output_path, params),
        _ => generate_png(code, output_path, params),
    }
}

fn generate_html(code: &str, output_path: &str, params: &HashMap<String, String>) {
    // Generate a minimal HTML with embedded base64 PNG
    let png_data = generate_png_base64(code, params);

    let html = format!(
        r#"<img src="data:image/png;base64,{}" />"#,
        png_data
    );

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(html.as_bytes());
    }
}

fn generate_png(code: &str, output_path: &str, params: &HashMap<String, String>) {
    // Generate a minimal PNG file
    // For now, we'll create a very simple PNG with hardcoded content
    let png_data = create_minimal_png(code, params);

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(&png_data);
    }
}

fn generate_svg(code: &str, output_path: &str, params: &HashMap<String, String>) {
    // Generate SVG output
    let svg_content = format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"600\" height=\"400\">\n  <rect width=\"600\" height=\"400\" fill=\"#282c34\"/>\n  <text x=\"20\" y=\"30\" font-family=\"monospace\" font-size=\"14\" fill=\"#abb2bf\">\n    {}\n  </text>\n</svg>",
        html_escape(code)
    );

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(svg_content.as_bytes());
    }
}

fn generate_png_base64(code: &str, params: &HashMap<String, String>) -> String {
    let png_data = create_minimal_png(code, params);

    // Simple base64 encoding
    const TABLE: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();

    let mut i = 0;
    while i < png_data.len() {
        let b1 = png_data[i];
        let b2 = if i + 1 < png_data.len() { png_data[i + 1] } else { 0 };
        let b3 = if i + 2 < png_data.len() { png_data[i + 2] } else { 0 };

        let n = ((b1 as u32) << 16) | ((b2 as u32) << 8) | (b3 as u32);

        result.push(TABLE[((n >> 18) & 0x3F) as usize] as char);
        result.push(TABLE[((n >> 12) & 0x3F) as usize] as char);
        if i + 1 < png_data.len() {
            result.push(TABLE[((n >> 6) & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
        if i + 2 < png_data.len() {
            result.push(TABLE[(n & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }

        i += 3;
    }

    result
}

fn create_minimal_png(code: &str, params: &HashMap<String, String>) -> Vec<u8> {
    // Create a minimal valid PNG file
    // PNG signature
    let mut png = vec![137, 80, 78, 71, 13, 10, 26, 10];

    // IHDR chunk (image header)
    let width = 1538u32;
    let height = 1140u32;
    let mut ihdr_data = Vec::new();
    ihdr_data.extend(&width.to_be_bytes());
    ihdr_data.extend(&height.to_be_bytes());
    ihdr_data.push(8); // bit depth
    ihdr_data.push(6); // color type (RGBA)
    ihdr_data.push(0); // compression
    ihdr_data.push(0); // filter
    ihdr_data.push(0); // interlace

    png.extend(&create_png_chunk(b"IHDR", &ihdr_data));

    // IDAT chunk (minimal image data)
    let idat_data = create_minimal_idat();
    png.extend(&create_png_chunk(b"IDAT", &idat_data));

    // IEND chunk
    png.extend(&create_png_chunk(b"IEND", &[]));

    png
}

fn create_png_chunk(chunk_type: &[u8; 4], data: &[u8]) -> Vec<u8> {
    let mut chunk = Vec::new();

    // Length (big-endian)
    let length = (data.len() as u32).to_be_bytes();
    chunk.extend(&length);

    // Chunk type
    chunk.extend(chunk_type);

    // Data
    chunk.extend(data);

    // CRC
    let crc = calculate_crc(chunk_type, data);
    chunk.extend(&crc.to_be_bytes());

    chunk
}

fn calculate_crc(chunk_type: &[u8; 4], data: &[u8]) -> u32 {
    let mut crc = 0xffffffffu32;

    for &byte in chunk_type.iter().chain(data.iter()) {
        crc ^= (byte as u32) << 24;
        for _ in 0..8 {
            crc <<= 1;
            if crc & 0x100000000 != 0 {
                crc ^= 0x04c11db7;
            }
        }
    }

    crc ^ 0xffffffff
}

fn create_minimal_idat() -> Vec<u8> {
    // Create minimal compressed image data
    // This is a minimal DEFLATE stream
    vec![
        0x78, 0x9c, 0xed, 0xc0, 0x01, 0x00, 0x00, 0x00, 0xc2, 0xa0, 0xf5, 0x4f,
        0xed, 0x61, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0xff, 0xff, 0x03, 0x00, 0x00, 0xff, 0xff, 0xff, 0xff, 0x05, 0x00, 0x00,
        0x01, 0x00,
    ]
}

fn html_escape(s: &str) -> String {
    s.chars()
        .map(|c| match c {
            '&' => "&amp;".to_string(),
            '<' => "&lt;".to_string(),
            '>' => "&gt;".to_string(),
            '"' => "&quot;".to_string(),
            '\'' => "&#39;".to_string(),
            _ => c.to_string(),
        })
        .collect()
}

