        "svg"
    } else {
        "png"
    };

    match format {
        "html" => generate_html(code, output_path, params),
        "png" => generate_png(code, output_path, params),
        "svg" => generate_svg(code, output_path, params),
        _ => generate_png(code, output_path, params),
    }
}

fn generate_html(code: &str, output_path: &str, _params: &HashMap<String, String>) {
    // Generate a minimal HTML with embedded base64 PNG
    let png_data = generate_png_base64(code, _params);

    let html = format!(
        r#"<img src="data:image/png;base64,{}" />"#,
        png_data
    );

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(html.as_bytes());
    }
}

fn generate_png(code: &str, output_path: &str, _params: &HashMap<String, String>) {
    // Generate a minimal PNG file
    let png_data = create_minimal_png(code, _params);

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(&png_data);
    }
}

