    );

    if let Ok(mut file) = fs::File::create(output_path) {
        let _ = file.write_all(svg_content.as_bytes());
    }
}

fn generate_png_base64(code: &str, _params: &HashMap<String, String>) -> String {
    let png_data = create_minimal_png(code, _params);

    // Simple base64 encoding
    const TABLE: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();

    let mut i = 0;
    while i < png_data.len() {
        let b1 = png_data[i];
        let b2 = if i + 1 < png_data.len() { png_data[i + 1] } else { 0 };
        let b3 = if i + 2 < png_data.len() { png_data[i + 2] } else { 0 };

        let n = ((b1 as u32) << 16) | ((b2 as u32) << 8) | (b3 as u32);

        result.push(TABLE[((n >> 18) & 0x3F) as usize] as char);
        result.push(TABLE[((n >> 12) & 0x3F) as usize] as char);
        if i + 1 < png_data.len() {
            result.push(TABLE[((n >> 6) & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
        if i + 2 < png_data.len() {
            result.push(TABLE[(n & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }

        i += 3;
    }

    result
}

fn create_minimal_png(_code: &str, _params: &HashMap<String, String>) -> Vec<u8> {
